def column_totals(rows):
    if not rows:
        return []
    num_cols = len(rows[0])
    totals = []
    for i in range(num_cols):
        col_sum = 0
        has_numeric = False
        for row in rows:
            if i < len(row):
                val = row[i]
                if isinstance(val, (int, float)):
                    col_sum += val
                    has_numeric = True
        if has_numeric:
            totals.append(col_sum)
        else:
            totals.append("")
    return totals

